      "content": "import pytest
from apps.policycore.core.coverage import COVERAGE_TIERS, TIER_MULTIPLIERS, upgrade_coverage
from apps.policycore.core.db import get_policy
from apps.policycore.core.seed import reseed

@pytest.fixture(autouse=True)
def setup_database():
    reseed()


def test_default_tier_is_standard_after_reseed():
    policy = get_policy("POL-10001")
    assert policy.coverage_tier == "Standard"


def test_upgrade_to_premium_recalculates_premium_and_persists():
    policy = upgrade_coverage("POL-10001", "Premium")
    assert policy.coverage_tier == "Premium"
    old_multiplier = TIER_MULTIPLIERS["Standard"]
    new_multiplier = TIER_MULTIPLIERS["Premium"]
    expected_premium = round(4820.50 / old_multiplier * new_multiplier, 2)
    assert policy.premium == expected_premium


def test_two_tier_upgrade_reaches_top_tier_and_stays_mathematically_consistent():
    policy = upgrade_coverage("POL-10001", "Premium")
    premium_at_premium_tier = policy.premium
    policy = upgrade_coverage("POL-10001", COVERAGE_TIERS[2])
    assert policy.coverage_tier == COVERAGE_TIERS[2]
    old_multiplier = TIER_MULTIPLIERS["Premium"]
    new_multiplier = TIER_MULTIPLIERS[COVERAGE_TIERS[2]]
    expected_premium = round(
        premium_at_premium_tier / old_multiplier * new_multiplier, 2
    )
    assert policy.premium == expected_premium


def test_upgrade_with_unknown_tier_raises_valueerror():
    with pytest.raises(ValueError):
        upgrade_coverage("POL-10001", "NotATier")


def test_downgrade_raises_valueerror():
    upgrade_coverage("POL-10001", "Premium")
    with pytest.raises(ValueError):
        upgrade_coverage("POL-10001", "Standard")


def test_same_tier_upgrade_raises_valueerror():
    with pytest.raises(ValueError):
        upgrade_coverage("POL-10001", "Standard")


def test_unknown_policy_raises_valueerror():
    with pytest.raises(ValueError):
        upgrade_coverage("POL-99999", "Premium")


def test_coverage_tiers_ordering():
    assert COVERAGE_TIERS == ["Standard", "Premium", COVERAGE_TIERS[2]]"
